-- 017: склад (РегистрНакопления.ПартииТоваровНаСкладахБухгалтерскийУчет) — конфиг извлечения 1С и shadow-цели ClickHouse.
-- Сгенерирован по аудиту docs/audits/Складские движения 1С … 2026-09-29.md. Факты в PostgreSQL не пишутся (pg_fact_write=false).
-- Идемпотентна: повторный запуск ничего не делает, если регистр stock уже заведён.
BEGIN;
CREATE SEQUENCE IF NOT EXISTS etl_meta.doc_key_stock_seq;
DO $$
DECLARE rid int; sid int; hsid int; th int; tp int; cs int; cp int;
BEGIN
  IF EXISTS (SELECT 1 FROM etl_meta.registers WHERE code = 'stock') THEN RAISE NOTICE 'stock уже заведён'; RETURN; END IF;
  VALUES ('stock', 'Складские движения', 'РегистрНакопления.ПартииТоваровНаСкладахБухгалтерскийУчет — только прямой путь в ClickHouse', 'incremental', 'stock_documents', 'document_uid', true, 'accumrg_with_documents', false, 'facts') RETURNING id INTO rid;
  VALUES (rid, 'stock', 'standalone', 'dbo', '_AccumRg17576', '[{alias}].[_Active] = 0x01', 0, true, 'РегистрНакопления.ПартииТоваровНаСкладахБухгалтерскийУчет', '_Period') RETURNING id INTO sid;
  VALUES ('fact_stock_shadow', 'SHADOW складских движений 1С → ClickHouse (fact_stock_shadow). Не активировать до PASS.', 'mssql_1c_conn', 'onec_register', 'stock', 'analytics_poc', 'fact_stock_shadow', 'toYYYYMM(period)', ARRAY['period', 'recorder_type', 'recorder']::text[], 'document_patch', 'period', 'month', ARRAY['recorder', 'recorder_type']::text[], 100000, 'fail', 3, 60, ARRAY['recorder', 'recorder_type', 'document_date', 'document_basis_guid']::text[], ARRAY[]::text[], '{"unique": [["recorder", "recorder_type"]], "not_zero": ["id"]}'::jsonb, 130, false, '{"own_id": true, "shadow": true, "target": "stock", "doc_key": ["recorder"], "state_key": "onec_register:stock:shadow", "signal_sources": [{"table": "stock_documents", "key_column": "document_uid", "updated_at_column": "updated_at"}, {"table": "transfers", "key_column": "guid", "updated_at_column": "updated_at"}, {"table": "adjustments", "key_column": "guid", "updated_at_column": "updated_at"}, {"table": "sales", "key_column": "document_uid", "updated_at_column": "updated_at", "filter": "doc_type IN (6, 10)"}]}'::jsonb, 'shadow_stock') RETURNING id INTO cs;
  VALUES ('fact_stock_positions_shadow', 'SHADOW складских движений 1С → ClickHouse (fact_stock_positions_shadow). Не активировать до PASS.', 'mssql_1c_conn', 'onec_register', 'stock', 'analytics_poc', 'fact_stock_positions_shadow', 'toYYYYMM(period)', ARRAY['period', 'sklad_id', 'nomenklatura_id', 'recorder', 'line_no']::text[], 'document_patch', 'period', 'month', ARRAY['recorder', 'recorder_type', 'line_no']::text[], 100000, 'fail', 3, 60, ARRAY['recorder', 'recorder_type', 'line_no', 'nomenklatura_id', 'sklad_id', 'kachestvo_id', 'kontragent_id', 'movement_type', 'operation_code', 'receipt_document_guid', 'supplier_order_guid']::text[], ARRAY['quantity', 'cost_amount']::text[], '{"unique": [["recorder", "recorder_type", "line_no"]], "not_zero": ["stock_id", "nomenklatura_id", "sklad_id"]}'::jsonb, 131, false, '{"parent": "stock", "shadow": true, "target": "stock_positions", "doc_key": ["recorder"], "state_key": "onec_register:stock:shadow", "parent_key": ["recorder", "recorder_type"], "parent_prefix": "hdr_"}'::jsonb, 'shadow_stock') RETURNING id INTO cp;
END $$;
VALUES ('shadow_stock', 'analytics_sync', 16, false, 'ch_sync', 'shadow складских движений 1С → ClickHouse; включается отдельно') ON CONFLICT (sync_group) DO NOTHING;
COMMIT;
